CREATE OR REPLACE FUNCTION public.finish_webhook_delivery(_id text,_token uuid,_http integer,_response text,_duration integer,_error text) RETURNS boolean LANGUAGE plpgsql SET search_path=public AS $$ DECLARE d public.webhook_deliveries; e public.webhook_endpoints; delay_s integer; success boolean; BEGIN SELECT * INTO d FROM public.webhook_deliveries WHERE id=_id AND claim_token=_token AND status='pending' FOR UPDATE; IF NOT FOUND THEN RETURN false; END IF; SELECT * INTO e FROM public.webhook_endpoints WHERE id=d.endpoint_id FOR UPDATE; success=(_http BETWEEN 200 AND 299 AND NULLIF(_error,'') IS NULL); UPDATE public.webhook_deliveries SET status=CASE WHEN success THEN 'succeeded' WHEN attempt=8 THEN 'exhausted' ELSE 'failed' END,response_status=NULLIF(_http,0),response_body=NULLIF(_response,''),duration_ms=GREATEST(_duration,0),error=NULLIF(_error,''),claim_token=NULL,lease_until=NULL WHERE id=d.id; IF e.deleted_at IS NOT NULL THEN RETURN true; END IF; IF success THEN UPDATE public.webhook_endpoints SET last_success_at=now(),failing_since=NULL WHERE id=e.id; ELSE UPDATE public.webhook_endpoints SET failing_since=COALESCE(failing_since,now()) WHERE id=e.id; IF d.attempt<8 THEN delay_s=(ARRAY[60,300,1800,7200,21600,43200,86400])[d.attempt]; INSERT INTO public.webhook_deliveries(id,event_id,endpoint_id,organization_id,integration_id,environment,cycle,attempt,next_attempt_at) VALUES('whd_'||replace(gen_random_uuid()::text,'-',''),d.event_id,d.endpoint_id,d.organization_id,d.integration_id,d.environment,d.cycle,d.attempt+1,now()+make_interval(secs=>delay_s)) ON CONFLICT DO NOTHING; END IF; END IF; RETURN true; END $$;
CREATE OR REPLACE FUNCTION public.integration_revocation_actors(_org uuid) RETURNS TABLE(id uuid,display_name text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT p.id,p.display_name FROM public.profiles p WHERE (public.is_org_member(_org) OR public.is_platform_admin()) AND EXISTS(SELECT 1 FROM public.integration_keys k WHERE k.organization_id=_org AND k.revoked_by=p.id) $$;
REVOKE ALL ON FUNCTION public.integration_revocation_actors(uuid) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.integration_revocation_actors(uuid) TO authenticated,service_role;